window.addEventListener('simplegames:media-start',e=>presence({currentGame:{kind:'media',title:e.detail.title}}));window.addEventListener('simplegames:media-stop',()=>presence({currentGame:null}));
$("#sign-out").onclick=async()=>{await updateDoc(doc(db,"users",auth.currentUser.uid),{status:"offline",lastActive:serverTimestamp(),currentGame:null}).catch(()=>{});await signOut(auth)};
onAuthStateChanged(auth,user=>{stopProfile();stopRequests();stopFriends();stopChats();stopMessages();stopBlocks();stopFriendProfiles.forEach(s=>s());stopFriendProfiles=[];clearInterval(presenceTimer);activeFriend=null;friends=[];chats.clear();friendProfiles.clear();chatsReady=false;document.dispatchEvent(new CustomEvent("simplegames:auth",{detail:{user}}));if(!user){profile=null;authView.hidden=false;socialView.hidden=true;$("#account-open .account-label").textContent="Log in";$("#account-unread").hidden=true;return}authView.hidden=true;socialView.hidden=false;showView("friends");$("#account-email").textContent=user.email||"";stopProfile=onSnapshot(doc(db,"users",user.uid),p=>{if(!p.exists())return;profile=p.data();const display=profile.displayName||profile.username,earned=badgeFor(profile);$("#profile-display-name").textContent=`${display}${earned?` ${earned}`:""}`;$("#profile-username").textContent=`@${profile.username}`;$("#account-open .account-label").textContent=display;$("#message-sound-setting").checked=profile.messageSound!==false;$("#dnd-setting").checked=!!profile.doNotDisturb;$("#hide-online-setting").checked=!!profile.hideOnline;$("#private-activity-setting").checked=!!profile.privateActivity;const f=$("#profile-form");if(document.activeElement?.form!==f){f.elements.displayName.value=display;f.elements.bio.value=profile.bio||"";$("#bio-count").textContent=(profile.bio||"").length}document.dispatchEvent(new CustomEvent("simplegames:profile",{detail:{user,profile}}))});listenRequests(user.uid);listenFriends(user.uid);listenChats(user.uid);listenBlocks(user.uid);presence();presenceTimer=setInterval(()=>{if(document.visibilityState==="visible")presence();renderFriends()},25000)});
onAuthStateChanged(auth,user=>{stopGroups();activeGroup=null;groups.clear();groupsReady=false;if(user)listenGroups(user.uid)});
onAuthStateChanged(auth,user=>{stopLeaderboard();if(user)listenLeaderboard()});
const renderFriendsBase=renderFriends;renderFriends=()=>{renderFriendsBase();updateAccountUnread()};
const openChatBase=openChat;openChat=f=>{const d=friendProfiles.get(f.uid);if(d)friendProfiles.set(f.uid,{...d,avatar:""});openChatBase(f);const shown=friendProfiles.get(f.uid)||f;$("#chat-title").textContent=shown.displayName||shown.username};
const fixedAccountLabel=$("#account-open .account-label");if(fixedAccountLabel){const keepAccountLabel=()=>{if(fixedAccountLabel.textContent!=="Account")fixedAccountLabel.textContent="Account"};keepAccountLabel();new MutationObserver(keepAccountLabel).observe(fixedAccountLabel,{childList:true,characterData:true,subtree:true})}
if(new URLSearchParams(location.search).has("user")){panel.hidden=false;showStatus("Log in to view this profile.")}
